def validar_chave(raw):
    chave = re.sub(r"\D", "", str(raw))
    if len(chave) != 44:
        return False, "A chave deve conter 44 dígitos.", chave
    if chave[20:22] != "55":
        return False, "A chave não corresponde a uma NF-e modelo 55.", chave
    soma = sum(int(d) * (2 + i % 8) for i, d in enumerate(chave[:43][::-1]))
    resto = soma % 11
    dv = 0 if resto < 2 else 11 - resto
    if dv != int(chave[-1]):
        return False, "Dígito verificador incorreto.", chave
    return True, "Chave estruturalmente válida (não confirma autorização fiscal).", chave


def linhas_da_pagina(pagina):
    # Agrupamento espacial: preserva a relação código / descrição / quantidade
    words = pagina.get_text("words")
    groups = {}
    for w in words:
        y = round(w[1] / 3) * 3
        groups.setdefault(y, []).append(w)
    return [(y, sorted(ws, key=lambda w:w[0])) for y,ws in sorted(groups.items())]


def ler_danfe(pdf_bytes):
    doc = fitz.open(stream=pdf_bytes, filetype="pdf")
    if doc.page_count > 30:
        doc.close()
        raise ValueError("PDF muito extenso (limite: 30 páginas).")
    itens = []
    textos = []
    for numero, pagina in enumerate(doc, 1):
        texto = pagina.get_text(sort=True)
        textos.append(texto)
        linhas = linhas_da_pagina(pagina)
        inicio = None
        fim = pagina.rect.height
        for y, ws in linhas:
            t = norm(" ".join(w[4] for w in ws))
            if "dados do produto" in t or "dados dos produtos" in t:
                inicio = y
            if inicio is not None and ("calculo do issqn" in t or "dados adicionais" in t) and y > inicio:
                fim = min(fim, y)
        if inicio is None:
            continue
        for y, ws in linhas:
            if y <= inicio + 5 or y >= fim:
                continue
            esquerda = [w for w in ws if w[0] < 80]
            candidatos = [w[4].strip() for w in esquerda if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._/-]{4,29}", w[4].strip())]
            if not candidatos:
                continue
            codigo = candidatos[0].upper()
            if codigo in {"PRODUTO", "CODIGO", "COD.", "NCM/SH"}:
                continue
            desc = " ".join(w[4] for w in ws if 78 <= w[0] < 215).strip()
            # Quantidade conforme coluna da DANFE deste cliente; caso não seja
            # identificável, nunca preencher automaticamente com 1.
            quantidade = ""
            for w in ws:
                if 310 <= w[0] <= 365 and re.fullmatch(r"\d+[.,]\d{2,4}", w[4]):
                    quantidade = w[4]
                    break
            if not desc or len(desc) < 4:
                continue
            itens.append({"Página": numero, "Código NF": codigo, "Descrição NF": desc, "Quantidade": quantidade})
    doc.close()
    texto_completo = "\n".join(textos)
    # Chave: captura os 44 dígitos no cabeçalho mesmo quando agrupados em blocos.
    chaves = set()
    for t in re.findall(r"(?:\d[ \t]*){44}", texto_completo):
        ok, _, chave = validar_chave(t)
        if ok:
            chaves.add(chave)
    # Alguns PDFs colocam espaços em grupos; pesquisa contextual no cabeçalho.
    for linha in texto_completo.splitlines():
        digitos = re.sub(r"\D", "", linha)
        if len(digitos) == 44:
            ok, _, chave = validar_chave(digitos)
            if ok:
                chaves.add(chave)
    return itens, sorted(chaves), texto_completo


# Regras operacionais: somente acessórios físicos, nunca refis ou fragrâncias.
# A presença de "REFIL", "LIQUIDO" etc. prevalece sobre a palavra "DIFUSOR".
VARIANTES_PORCELANA = ("LAVANDA", "ORQUIDEA", "CAMELIA", "BORBOLETA", "PASSAROS", "LOTUS", "TULIPA", "CHA BRANCO", "COSTELA DE ADAO")
VARIANTES_CRISTAL = ("PROTEA", "BROMELIA")
PALAVRAS_CONTEUDO = ("REFIL", "ESSENCIA", "FRAGRANCIA", "PERFUME", "LIQUIDO", "AROMATIZADOR", "OLEO", "SPRAY", "AEROSSOL", "290ML", "15G")
UTENSILIOS_SOLIDOS = (
    "PRATO", "PRATOS", "TALHER", "GARFO", "COLHER", "XICARA", "TRAVESSA",
    "PIRES", "CANECA", "TACA", "COPO", "BANDEJA", "NECESSAIRE",
    "PORTA RETRATO", "PORTA GUARDANAPO", "VASO", "SOUSPLAT",
)
POTENCIAL_FDS = ("SABONETE", "HIDRATANTE", "DESODORANTE", "DEO ", "VELA", "DIFUSOR", "REFIL", "PERFUME", "FRAGRANCIA", "ESSENCIA", "SPRAY", "AROMATIZADOR", "OLEO", "ALCOOL", "COSMETICO")


def tipo_difusor_automotivo(descricao):
    """Separa aparelho metálico de refil/odorizante (produtos distintos)."""
    d = norm(descricao).upper()
    d = re.sub(r"\s+", " ", d)
    if re.search(r"\b(?:ODORIZANTE|REFIL|AROMATIZADOR|ESSENCIA|FRAGRANCIA|PERFUME)\b", d) and ("CARRO" in d or "AUTOMOT" in d):
        return "REFIL"
    if "DIFUSOR" in d and ("CARRO" in d or "AUTOMOT" in d):
        if re.search(r"\b(?:KIT|COMBO|CONJUNTO|COM REFIL|C/ REFIL|COM ODORIZANTE|C/ ODORIZANTE)\b", d):
            return "KIT"
        if re.search(r"\b(?:LIQUIDO|FRAGRANCIA|ESSENCIA|OLEO|SPRAY)\b", d):
            return "REFIL"
        return "APARELHO"
    return None


def regra_acessorio(descricao):
    d = norm(descricao).upper()
    d = re.sub(r"\s+", " ", d)
    if any(termo in d for termo in PALAVRAS_CONTEUDO):
        return None
    if tipo_difusor_automotivo(descricao) == "APARELHO":
        # DANFEs da TB podem abreviar a descrição antes da cor.
        return "Difusor para carro (acessório físico, sem refil)"
    if "DIFUSOR DE PORCELANA" in d:
        return "Difusor de porcelana (acessório físico, sem refil)"
    if "DIFUSOR DE CRISTAL" in d:
        return "Difusor de cristal (acessório físico, sem refil)"
    return None


def regra_utensilio(descricao):
    d = norm(descricao).upper()
    if any(termo in d for termo in PALAVRAS_CONTEUDO):
        return None
    # Evita falsos positivos de fragmentos como "copo" dentro de outra palavra.
    if any(re.search(r"\b" + re.escape(t) + r"\b", d) for t in UTENSILIOS_SOLIDOS):
        return "Utensílio/acessório comum, sem conteúdo químico declarado"
    return None


def assinatura_produto(descricao):
    """Nome-base sem embalagem/volume, preservando família, fragrância e formulação."""
    d = norm(descricao).upper()
    d = re.sub(r"\b(?:KIT|CONJUNTO|PACK|COMBO|ESTOJO|CAIXA|CX)\b", " ", d)
    d = re.sub(r"\b\d+(?:[.,]\d+)?\s*(?:ML|LITROS?|LTS?|LT|KG|GR|GRAMAS?|G|UNIDADES?|UN|PCS|PECAS?)\b", " ", d)
    d = re.sub(r"\b(?:C/|COM)\s*\d+\b", " ", d)
    d = re.sub(r"[^A-Z0-9 ]", " ", d)
    return " ".join(d.split())


def possivel_kit(descricao):
    d = norm(descricao).upper()
    return bool(re.search(r"\b(KIT|CONJUNTO|PACK|COMBO|ESTOJO)\b|\b\d+\s*(?:PCS|PECAS|UNIDADES|UN)\b", d))


def status_consensual(registros):
    validos = [r for r in registros if r["STATUS"] in ("NOR", "DG")]
    classes = {r["STATUS"] for r in validos}
    return (next(iter(classes)), validos[0]["DESCRICAO"]) if len(classes) == 1 else (None, "")


# Persistência no mesmo método dos outros apps: arquivo JSON privado via GitHub API.
# Configurar GITHUB_TOKEN, GITHUB_REPO, ADMIN_PASSWORD em Streamlit Secrets.
